import android.app.Activity;
import androidx.core.os.LocaleListCompat;
import com.adapty.Adapty;
import com.adapty.models.AdaptyFlow;
import com.adapty.ui.AdaptyCustomAssets;
import com.adapty.ui.AdaptyFlowInsets;
import com.adapty.ui.AdaptyFlowView;
import com.adapty.ui.AdaptyUI;
import com.adapty.ui.listeners.AdaptyFlowDefaultEventListener;
import com.adapty.ui.listeners.AdaptyUiTagResolver;
import com.adapty.ui.listeners.AdaptyUiTimerResolver;
import com.adapty.utils.AdaptyResult;
import java.util.Arrays;
import java.util.List;

public class WeightPaywall {
    public static void showWeightPaywall(Activity activity, double currentWeight, double goalWeight) {
        WeightPlan plan = new WeightPlan(currentWeight, goalWeight);
        Adapty.getFlow("weight_paywall", flowResult -> {
            if (!(flowResult instanceof AdaptyResult.Success)) return; // handle the error
            AdaptyFlow flow = ((AdaptyResult.Success<AdaptyFlow>) flowResult).getValue();
            List<String> preferredLocales =
                Arrays.asList(LocaleListCompat.getAdjustedDefault().toLanguageTags().split(","));
            AdaptyUI.getFlowConfiguration(flow, preferredLocales, configResult -> {
                if (!(configResult instanceof AdaptyResult.Success)) return; // handle the error
                AdaptyFlowView flowView = AdaptyUI.getFlowView(
                        activity,
                        ((AdaptyResult.Success<AdaptyUI.FlowConfiguration>) configResult).getValue(),
                        null, // products
                        new AdaptyFlowDefaultEventListener(),
                        // defaults: if your app passes other values here, keep them
                        AdaptyFlowInsets.Unspecified,
                        AdaptyCustomAssets.Empty,
                        AdaptyUiTagResolver.Default,
                        AdaptyUiTimerResolver.Default,
                        null, // observerModeHandler
                        new WeightChartResolver(plan)
                );
                activity.setContentView(flowView); // in place of the onboarding flow
            });
        });
    }
}
